#!/usr/bin/env python3
import json,statistics
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[3];x=json.loads((ROOT/'results/v4_euclidean/downstream/CONSOLIDATED_SUITE_RESULTS.json').read_text());insp=json.loads((ROOT/'results/v4_euclidean/downstream/SUITE_PREPERFORMANCE_INSPECTION.json').read_text());OUT=ROOT/'reproducibility/v4_euclidean/CONSOLIDATED_DOWNSTREAM_REPORT.md';S=('424242','271828','314159')
def f(v):return f'{v:.6f}'
def method_label(m):return {'token_weighted_leaf_mean':'token-weighted','unweighted_leaf_mean':'unweighted','direct_teacher':'direct CLS'}.get(m,m.replace('recursive_seed','V4 seed '))
lines=['# Consolidated frozen V4 downstream benchmark report','','## Protocol and provenance','','No V4 model was trained, selected, or altered for this suite. All recursive results use the three frozen Euclidean-residual checkpoints. The teacher is normalized documented `last_hidden_state[:,0]` from `Alibaba-NLP/gte-modernbert-base@e7f32e3c00f91d699e8c43b53106206bcc72bb22`.','','LongEmbed is pinned to `dwzhu/LongEmbed@10039a580487dacecf79db69166e17ace3ede392`. Every benchmark file was verified content-identical to MTEB metadata revision `6e346642246bfb4928c560ee08640dc84d074e8c`. The official `corpus`, `queries`, and `qrels` configurations are evaluated as the test set. NFCorpus uses the BEIR test split and archive SHA-256 `efe5be03f8c5b86a5870102d0599d227c8c6e2484328e68c6522560385671b0b`.','','Each task uses one hash-checked CLS leaf cache shared tensor-identically by all recursive seeds and both pooling baselines. Queries use direct CLS. Metrics are BEIR-compatible `pytrec_eval` nDCG/recall plus reciprocal rank over the same deterministic rankings. Query bootstrap confidence intervals use 1,000 replicates. Direct CLS appears only when a complete candidate corpus/condition fits without truncation.','','## Dataset scale','','| task | documents | queries | total tokens | total leaves | merges | max depth | token median / p90 / max | leaf median / p90 / max |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for t,z in x['real_world'].items():
 c=z['counts']
 if t in insp['tasks']:d=insp['tasks'][t]['documents'];tok=d['tokens'];lea=d['leaves'];tail=f"{tok['median']:.0f} / {tok['p90']:.0f} / {tok['max']}";ll=f"{lea['median']:.0f} / {lea['p90']:.0f} / {lea['max']}"
 else:
  m=json.loads((ROOT/'results/v4_euclidean/downstream/nfcorpus/leaf_cache/MANIFEST.json').read_text());tv=[a['tokens'] for a in m['documents']];lv=[a['leaves'] for a in m['documents']];tail=f'{np.median(tv):.0f} / {np.quantile(tv,.9):.0f} / {max(tv)}';ll=f'{np.median(lv):.0f} / {np.quantile(lv,.9):.0f} / {max(lv)}'
 lines.append(f"| {t} | {c['documents']} | {c['queries']} | {c['tokens']} | {c['leaves']} | {c['merges']} | {c['max_depth']} | {tail} | {ll} |")
lines+=['','Per-document token count, leaf count, recursion depth, merge count, and synthetic context condition are preserved in `results/v4_euclidean/publication_sources/document_scale_metadata.csv`.','','## Real-world retrieval','','All values are on 0–1 scale. “V4 mean” is the arithmetic mean of the three frozen-seed metrics.','','| task | method | nDCG@10 | Recall@10 | Recall@100 | MRR@10 |','|---|---|---:|---:|---:|---:|']
for t,z in x['real_world'].items():
 order=[f'recursive_seed{s}' for s in S]+['recursive_three_seed_mean','token_weighted_leaf_mean','unweighted_leaf_mean','direct_teacher']
 for m in order:
  if m not in z['methods']:continue
  a=z['methods'][m];label='V4 mean' if m=='recursive_three_seed_mean' else method_label(m);lines.append(f"| {t} | {label} | {f(a['nDCG@10'])} | {f(a['Recall@10'])} | {f(a['Recall@100'])} | {f(a['MRR@10'])} |")
lines+=['','V4-mean nDCG@10 query-bootstrap intervals and paired pooling gaps:','','| task | V4 nDCG@10 95% CI | V4 − token-weighted (95% paired CI) | V4 − unweighted (95% paired CI) |','|---|---:|---:|---:|']
for t,z in x['real_world'].items():
 ci=z['method_ci95']['recursive_three_seed_mean']['nDCG@10'];w=z['gaps']['token_weighted_leaf_mean'];u=z['gaps']['unweighted_leaf_mean'];wc=w['overall_paired_ci95']['nDCG@10'];uc=u['overall_paired_ci95']['nDCG@10'];lines.append(f"| {t} | [{f(ci[0])}, {f(ci[1])}] | {f(w['overall']['nDCG@10'])} [{f(wc[0])}, {f(wc[1])}] | {f(u['overall']['nDCG@10'])} [{f(uc[0])}, {f(uc[1])}] |")
lines+=['','Direct CLS is present for NFCorpus. It is excluded from every real LongEmbed task because at least one corpus document exceeds 8,190 raw teacher tokens; no truncated subset was substituted.','','## Scale-stratified result','','Bins were frozen before model evaluation. Detailed token/leaf/depth values, all requested metrics, query counts, and paired confidence intervals are in `CONSOLIDATED_SUITE_RESULTS.json` and the publication CSVs. The clearest nDCG@10 comparisons against token-weighted pooling are:','','- NarrativeQA: +0.0574 at 4,097–8,190 tokens, +0.0367 at 8,191–16,384, then −0.0154 at 32,769–65,536 and −0.0135 above 65,536. At depth 5 (318 queries), the gap is −0.0355, 95% CI [−0.0504, −0.0215].','- QMSum: −0.0179 at 8,191–16,384 and −0.0255 at 16,385–32,768. At depth 3 (507 queries), the gap is −0.0253 [−0.0420, −0.0108].','- 2WikiMultihopQA: +0.0182 at 4,097–8,190 and +0.0129 at 8,191–16,384, with confidence intervals spanning zero.','- SummScreenFD: gaps are small and non-monotonic; the overall +0.00368 and all substantive strata intervals include zero.','','Thus there is no increasing recursive advantage with token count, leaf count, or depth. On the two datasets with substantial genuinely deep populations, the longest/deepest strata favor simple pooling.','','## LongEmbed Needle and Passkey','','The standard eight context conditions are evaluated independently with 100 candidate documents and 50 queries each. The official synthetic main score is nDCG@1. Direct CLS is shown only through context 8,192, where every actual tokenized document fits.','','| task | context | V4 mean | token-weighted | unweighted | direct CLS |','|---|---:|---:|---:|---:|---:|']
for t,z in x['synthetic'].items():
 for c,v in sorted(z['contexts'].items(),key=lambda q:int(q[0])):
  def g(m):return f(v[m]['metrics']['nDCG@1']) if m in v else '—'
  lines.append(f"| {t} | {c} | {g('recursive_three_seed_mean')} | {g('token_weighted_leaf_mean')} | {g('unweighted_leaf_mean')} | {g('direct_teacher')} |")
lines+=['','Across-context nDCG@1 means: Needle V4 0.2750 versus token-weighted 0.2900 and unweighted 0.2800; Passkey V4 0.4833 versus 0.5925 and 0.5925. Performance falls sharply with context length for every method. Recursive composition does not improve that scaling and is especially worse on Passkey.','','## ECtHR-A multilabel classification','','Frozen representations use official train/validation/test separation, one-vs-rest logistic regression, a predeclared probability threshold of 0.5, validation micro-F1 selection over the frozen C grid with smaller-C tie breaking, refit on train+validation, and one test evaluation.','','| method | micro-F1 | macro-F1 |','|---|---:|---:|']
n=x['nonretrieval']
for m,z in n['ecthr_a'].items():lines.append(f"| {method_label(m)} | {f(z['test']['micro_f1'])} | {f(z['test']['macro_f1'])} |")
mic=statistics.mean(n['ecthr_a'][f'recursive_seed{s}']['test']['micro_f1'] for s in S);mac=statistics.mean(n['ecthr_a'][f'recursive_seed{s}']['test']['macro_f1'] for s in S);lines.append(f'| **V4 mean** | **{f(mic)}** | **{f(mac)}** |')
lines+=['','V4 exceeds both pooling baselines on this frozen linear-probe task (mean micro-F1 0.643946; macro-F1 0.531362).','','## 20 Newsgroups clustering','','All representations use identical fixed K-means seeds/settings.','','| method | NMI | ARI |','|---|---:|---:|']
for m,z in n['20_newsgroups'].items():lines.append(f"| {method_label(m)} | {f(z['nmi'])} | {f(z['ari'])} |")
nmi=statistics.mean(n['20_newsgroups'][f'recursive_seed{s}']['nmi'] for s in S);ari=statistics.mean(n['20_newsgroups'][f'recursive_seed{s}']['ari'] for s in S);lines.append(f'| **V4 mean** | **{f(nmi)}** | **{f(ari)}** |')
lines+=['','V4 is approximately tied with token-weighted pooling and below unweighted pooling.','','## Failures, exclusions, and audit notes','','- New-task schema/ID/qrel inspection found no malformed, duplicate, missing, or qrel-referenced absent examples. Metric evaluation dropped no queries.','- The first QMSum recursive pass encountered a telemetry API invocation error before any metric or result was computed. Engineering amendment 1 changed only positional arguments to required keyword arguments; caches, embeddings, rankings, models, bins, and metrics were unchanged.','- Needle and Passkey were computationally feasible; neither was excluded or altered.','- Direct teacher exclusions are solely context-window validity exclusions described above.','- ECtHR-A and 20 Newsgroups were already run under the frozen V4 downstream protocol and were not retuned.','','## Factual conclusion','','V4 does **not materially outperform simple pooling overall**, and it does not gain relative advantage on genuinely long/deep documents. It modestly improves 2WikiMultihopQA and SummScreenFD, loses on NarrativeQA and QMSum, loses the synthetic context-scaling comparison—substantially on Passkey—and is worse in the deepest NarrativeQA/QMSum strata. Its clearest downstream gain is ECtHR-A linear classification, while clustering is no better than pooling.','','All machine-readable results, confidence intervals, document metadata, figure sources, and figures are under `results/v4_euclidean/` and `figures/v4_euclidean/downstream_suite/`.']
OUT.write_text('\n'.join(lines)+'\n');print(OUT)
